"""Post-outcome lossless archive/contract export, never a new search."""
import argparse,collections,datetime,gzip,hashlib,json,math
from pathlib import Path
import curved_sampler as c
ROOT=Path(__file__).resolve().parents[1]
def run(source,poses,destination):
 dest=Path(destination);dest.mkdir(exist_ok=True,parents=True);raw=Path(source).read_bytes();r=json.loads(raw);archive=dest/'CURVED-SAMPLER-036-ORIGINAL.json.gz';archive.write_bytes(gzip.compress(raw,mtime=0));poseout=dest/'CURVED-SAMPLER-036-poses.jsonl.gz';poseout.write_bytes(Path(poses).read_bytes());sw=r['stages']['sweep'];assert hashlib.sha256(poseout.read_bytes()).hexdigest()==sw['pose_records_sha256'];rows=json.loads((ROOT/'data/monument-fold-transcript-v1.json').read_text())['tableau_rows'];complete=[]
 with gzip.open(poses,'rt') as f:
  for line in f:
   row=json.loads(line)
   if row['complete']:complete.append(row)
 best=sorted(sw['utility_rows'],key=lambda x:(-x['minimum_margin'],tuple(x['params'][k] for k in ('D','H','s','aim_deg','tx','ty','rotation_deg','pitch'))))[0] if sw['utility_rows'] else None
 fixture=dict(id='CURVED-SAMPLER-036-SITE-FIXTURES-v1',generated_at_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),source_raw_sha256=hashlib.sha256(raw).hexdigest(),tableau_rows=rows,reticle=c.RETICLE,numeric_tolerance_absolute=1e-9,scientific_status='Invented ideal mirror, nominal key possible; no tested utility pose stable under declared tolerance/pupil panels; no actual K4 test',nominal=None,assembly_failure=None,pupil_failure=None,synthetic_plant=None)
 if best:
  params=best['params'];nominal=c.sample(params,rows);fixture['nominal']=nominal;st=next(x for x in r['stages']['stability']['records'] if x['id']==best['id']);fixture['assembly_failure']=st['first_counterexample'];failure=next(x for x in st['records'] if x['id'].startswith('pupil-0.05-rim-') and not x['same_cells']);index=int(failure['id'].rsplit('-',1)[1]);_,right,up=c.basis(params['aim_deg']);a=index*math.pi/4;size=.05/250;offset=c.add(tuple(size*math.cos(a)*x for x in right),up,size*math.sin(a));fixture['pupil_failure']=dict(params=params,eye_offset=offset,fixed_reticle=True,pupil_radius_mm=.05,sample=c.sample(params,rows,offset,True));fixture['synthetic_plant']=next(x for x in r['stages']['recovery']['plants'] if x['planted_key']==best['key'])
 (dest/'CURVED-SAMPLER-036-SITE-FIXTURES.json').write_text(json.dumps(fixture,indent=2)+'\n')
 summary=dict(id='CURVED-SAMPLER-036',kind='Complete synthetic ideal-mirror feasibility, tolerance failure and supplied-panel recovery; not actual K4',started_at_utc=r['started_at_utc'],finished_at_utc=r['finished_at_utc'],complete=r['complete'],peak_rss_bytes=r['peak_rss_bytes'],actual_K4_evaluations=0,source_sha256=r['source_sha256'],archives={str(archive.name):dict(sha256=hashlib.sha256(archive.read_bytes()).hexdigest(),raw_sha256=hashlib.sha256(raw).hexdigest(),bytes=archive.stat().st_size),str(poseout.name):dict(sha256=hashlib.sha256(poseout.read_bytes()).hexdigest(),bytes=poseout.stat().st_size)},sweep={k:v for k,v in sw.items() if k not in ('footprints','utility_rows','key_panel')},key_classes=dict(complete97_poses=len(complete),distinct_complete_keys=len({x['key'] for x in complete}),distinct_complete_cellpaths=len({json.dumps(x['cells']) for x in complete}),utility_key_classes=len(sw['key_panel']),all_complete_distinct_cells=sorted({x['distinct_cells'] for x in complete}),all_complete_distinct_letters=sorted({x['distinct_letters'] for x in complete})),utility_rows=sw['utility_rows'],stability=[dict(id=x['id'],assembly_cell_stable=x['assembly_cell_stable'],assembly_key_stable=x['assembly_key_stable'],pupil=x['pupil'],tested_perturbations=len(x['records'])) for x in r['stages']['stability']['records']],recovery=dict(complete=r['stages']['recovery']['complete'],plants=len(r['stages']['recovery']['plants']),first13_key_counts=[len(x['result']['first13_key_classes']) for x in r['stages']['recovery']['plants']],full24_key_counts=[len(x['result']['full24_candidates']) for x in r['stages']['recovery']['plants']],null_draws=len(r['stages']['recovery']['nulls']),null_whole_family_maxima=[x['whole_family_maximum'] for x in r['stages']['recovery']['nulls']],null_full24_matches=sum(x['full24_key_classes'] for x in r['stages']['recovery']['nulls'])))
 (dest/'CURVED-SAMPLER-036-SUMMARY.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps(dict(key_classes=summary['key_classes'],archives=summary['archives']),indent=2))
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--source',required=True);ap.add_argument('--poses',required=True);ap.add_argument('--destination',required=True);a=ap.parse_args();run(a.source,a.poses,a.destination)
